{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2159-09-11 23:15:00",
      "speaker": "Doctor",
      "text": "Hi Ms. ___, I’m Dr. ___. You came in tonight with nausea and vomiting. Can you tell me more about what’s been going on?"
    },
    {
      "turn_number": 2,
      "time": "2159-09-11 23:16:00",
      "speaker": "Patient",
      "text": "Yes, I’ve been feeling sick since yesterday. I couldn’t keep anything down, not even my blood pressure pills. I’ve been vomiting a few times."
    },
    {
      "turn_number": 3,
      "time": "2159-09-11 23:17:00",
      "speaker": "Doctor",
      "text": "I see. Your blood pressure was very high when you arrived—over 250. That can definitely cause nausea. Did you miss any doses recently?"
    },
    {
      "turn_number": 4,
      "time": "2159-09-11 23:18:00",
      "speaker": "Patient",
      "text": "I try to take them, but sometimes in the evening it’s high, and then during dialysis it drops too low. I get dizzy."
    },
    {
      "turn_number": 5,
      "time": "2159-09-11 23:19:00",
      "speaker": "Doctor",
      "text": "That makes sense. We’ll manage your blood pressure carefully here. We also noticed a small finding on your brain scan—there’s a faint spot in the medulla. It could be nothing, but we recommend an MRI to check."
    },
    {
      "turn_number": 6,
      "time": "2159-09-11 23:20:00",
      "speaker": "Patient",
      "text": "An MRI? Is that serious? I’m already so anxious."
    },
    {
      "turn_number": 7,
      "time": "2159-09-11 23:21:00",
      "speaker": "Doctor",
      "text": "It’s precautionary. It might be just an artifact, but we want to be sure. We’ll discuss risks and benefits with you and your husband."
    },
    {
      "turn_number": 8,
      "time": "2159-09-12 08:30:00",
      "speaker": "Doctor",
      "text": "Good morning. Your CT head showed that small area we discussed. The team recommends MRI, but we understand if you’re not comfortable with it."
    },
    {
      "turn_number": 9,
      "time": "2159-09-12 08:31:00",
      "speaker": "Patient",
      "text": "After talking with my husband, we’d rather not do the MRI. Can we just watch it?"
    },
    {
      "turn_number": 10,
      "time": "2159-09-12 08:32:00",
      "speaker": "Doctor",
      "text": "Yes, that’s your choice. We’ll document that and follow up with your neurologist if needed. For now, we’re focusing on your blood pressure and preparing for your planned toe surgery."
    },
    {
      "turn_number": 11,
      "time": "2159-09-12 14:00:00",
      "speaker": "Doctor",
      "text": "Your labs show your kidney function is stable, though your anion gap is a bit high. We think it’s from the sodium thiosulfate used in dialysis."
    },
    {
      "turn_number": 12,
      "time": "2159-09-12 14:01:00",
      "speaker": "Patient",
      "text": "Does that mean something’s wrong with my dialysis?"
    },
    {
      "turn_number": 13,
      "time": "2159-09-12 14:02:00",
      "speaker": "Doctor",
      "text": "Not necessarily. It’s a known effect. We’ll monitor it. Your troponin is slightly elevated, but likely due to stress from vomiting and high BP, not a heart attack."
    },
    {
      "turn_number": 14,
      "time": "2159-09-13 09:00:00",
      "speaker": "Doctor",
      "text": "We’re transferring you to Vascular Surgery today. They’ll manage your upcoming toe amputation. You were scheduled for a TMA, but we’ll see what’s best."
    },
    {
      "turn_number": 15,
      "time": "2159-09-13 09:01:00",
      "speaker": "Patient",
      "text": "Is the gangrene worse? I was hoping it might improve."
    },
    {
      "turn_number": 16,
      "time": "2159-09-13 09:02:00",
      "speaker": "Doctor",
      "text": "Actually, it’s looking a bit better. We may only need to remove one or two toes instead of a larger amputation. We’ll decide in the OR."
    },
    {
      "turn_number": 17,
      "time": "2159-09-14 07:00:00",
      "speaker": "Doctor",
      "text": "Good morning. You’re due for dialysis today. After that, we’ll finalize plans for surgery tomorrow."
    },
    {
      "turn_number": 18,
      "time": "2159-09-14 07:01:00",
      "speaker": "Patient",
      "text": "Will I be on heparin again like last time?"
    },
    {
      "turn_number": 19,
      "time": "2159-09-14 07:02:00",
      "speaker": "Doctor",
      "text": "Yes, we’ve started a heparin drip to keep your blood thin, especially with your mechanical valve. Your INR was low on admission."
    },
    {
      "turn_number": 20,
      "time": "2159-09-14 13:30:00",
      "speaker": "Doctor",
      "text": "After dialysis, your blood pressure spiked again. We gave IV hydralazine, and it’s coming down. The chest X-ray shows fluid in your lungs—common with volume overload."
    },
    {
      "turn_number": 21,
      "time": "2159-09-14 13:31:00",
      "speaker": "Patient",
      "text": "So that’s why I felt short of breath?"
    },
    {
      "turn_number": 22,
      "time": "2159-09-14 13:32:00",
      "speaker": "Doctor",
      "text": "Exactly. Dialysis should help remove the extra fluid. We’ll keep monitoring your BP."
    },
    {
      "turn_number": 23,
      "time": "2159-09-15 06:00:00",
      "speaker": "Doctor",
      "text": "You had another episode of nausea and high BP this morning. We gave you a scopolamine patch and Zofran. O2 helped with the breathing."
    },
    {
      "turn_number": 24,
      "time": "2159-09-15 06:01:00",
      "speaker": "Patient",
      "text": "I’m ready for this over with. When’s the surgery?"
    },
    {
      "turn_number": 25,
      "time": "2159-09-15 06:02:00",
      "speaker": "Doctor",
      "text": "You’re going to the OR in a few hours. You’ll have a left toe amputation—likely just the first and second toes. You’ll be under anesthesia and wake up in recovery."
    },
    {
      "turn_number": 26,
      "time": "2159-09-15 14:00:00",
      "speaker": "Doctor",
      "text": "Hi, you’re back. The surgery went well. You had amputation of the first and second toes on the left foot. The gangrene was limited, so we didn’t need a larger procedure."
    },
    {
      "turn_number": 27,
      "time": "2159-09-15 14:01:00",
      "speaker": "Patient",
      "text": "That’s a relief. Is the wound okay?"
    },
    {
      "turn_number": 28,
      "time": "2159-09-15 14:02:00",
      "speaker": "Doctor",
      "text": "It looks clean. We’ll keep an eye on it. You’re on Dilaudid for pain—we increased the dose because your foot hurt more after dialysis."
    },
    {
      "turn_number": 29,
      "time": "2159-09-16 08:00:00",
      "speaker": "Doctor",
      "text": "Good news—your nausea is gone, and you’re eating. BP is much better—120s over 70s—on labetalol, amlodipine, and hydralazine."
    },
    {
      "turn_number": 30,
      "time": "2159-09-16 08:01:00",
      "speaker": "Patient",
      "text": "Why the new blood pressure meds?"
    },
    {
      "turn_number": 31,
      "time": "2159-09-16 08:02:00",
      "speaker": "Doctor",
      "text": "Cardiology and Nephrology suggested switching from metoprolol to labetalol—it’s better for patients on dialysis. Hydralazine helps too."
    },
    {
      "turn_number": 32,
      "time": "2159-09-16 08:03:00",
      "speaker": "Patient",
      "text": "And the warfarin? I was on that before."
    },
    {
      "turn_number": 33,
      "time": "2159-09-16 08:04:00",
      "speaker": "Doctor",
      "text": "We restarted Coumadin yesterday. Your INR hit 2.0, so we stopped the heparin drip. You’ll go home on warfarin—5 mg tonight."
    },
    {
      "turn_number": 34,
      "time": "2159-09-16 08:05:00",
      "speaker": "Patient",
      "text": "Should I watch for bleeding?"
    },
    {
      "turn_number": 35,
      "time": "2159-09-16 08:06:00",
      "speaker": "Doctor",
      "text": "Yes—watch for unusual bruising, nosebleeds, or dark stools. Your PCP will manage your INR checks."
    },
    {
      "turn_number": 36,
      "time": "2159-09-16 13:00:00",
      "speaker": "Doctor",
      "text": "Your wound vac on the right stump was changed today—looks great with healthy tissue. Left foot wound is clean too."
    },
    {
      "turn_number": 37,
      "time": "2159-09-16 13:01:00",
      "speaker": "Patient",
      "text": "I’m glad it’s healing. What about driving or walking?"
    },
    {
      "turn_number": 38,
      "time": "2159-09-16 13:02:00",
      "speaker": "Doctor",
      "text": "No driving until cleared. You can use your heel to pivot, but keep the left foot elevated when possible. No heavy lifting over 20 pounds."
    },
    {
      "turn_number": 39,
      "time": "2159-09-16 13:03:00",
      "speaker": "Patient",
      "text": "Can I shower?"
    },
    {
      "turn_number": 40,
      "time": "2159-09-16 13:04:00",
      "speaker": "Doctor",
      "text": "Yes, but don’t soak the foot. No baths or pools for four weeks. Sutures come out in about three weeks at your vascular clinic visit."
    },
    {
      "turn_number": 41,
      "time": "2159-09-17 07:00:00",
      "speaker": "Doctor",
      "text": "You’re doing really well. We’re clearing you for discharge today. You’ll have home health for wound care and PT."
    },
    {
      "turn_number": 42,
      "time": "2159-09-17 07:01:00",
      "speaker": "Patient",
      "text": "That’s great. What about my blood pressure meds long-term?"
    },
    {
      "turn_number": 43,
      "time": "2159-09-17 07:02:00",
      "speaker": "Doctor",
      "text": "Cardiology suggested lisinopril instead of hydralazine, but we’ll let your nephrologist decide. You have an appointment with Dr. ___ this week?"
    },
    {
      "turn_number": 44,
      "time": "2159-09-17 07:03:00",
      "speaker": "Patient",
      "text": "Yes, I do. And I’ll see the vascular surgeon for stitches?"
    },
    {
      "turn_number": 45,
      "time": "2159-09-17 07:04:00",
      "speaker": "Doctor",
      "text": "Yes, in about three weeks. Call if you see redness, drainage, fever, or new pain in the foot."
    },
    {
      "turn_number": 46,
      "time": "2159-09-17 07:05:00",
      "speaker": "Patient",
      "text": "And the pain meds? They make me constipated."
    },
    {
      "turn_number": 47,
      "time": "2159-09-17 07:06:00",
      "speaker": "Doctor",
      "text": "Take them as needed. Increase fiber and fluids. We’ve included stool softeners in your instructions."
    },
    {
      "turn_number": 48,
      "time": "2159-09-17 07:07:00",
      "speaker": "Patient",
      "text": "I’ll try. Thank you for everything."
    },
    {
      "turn_number": 49,
      "time": "2159-09-17 07:08:00",
      "speaker": "Doctor",
      "text": "You’re welcome. We’ve set up a cardiology appointment too. Take care, and follow up closely."
    },
    {
      "turn_number": 50,
      "time": "2159-09-17 07:09:00",
      "speaker": "Patient",
      "text": "I will. I’m just glad to be going home."
    },
    {
      "turn_number": 51,
      "time": "2159-09-17 07:10:00",
      "speaker": "Doctor",
      "text": "We’ll get your discharge papers ready. The home health team will be there this afternoon."
    },
    {
      "turn_number": 52,
      "time": "2159-09-17 07:11:00",
      "speaker": "Patient",
      "text": "And I take warfarin tonight, right?"
    },
    {
      "turn_number": 53,
      "time": "2159-09-17 07:12:00",
      "speaker": "Doctor",
      "text": "Yes, 5 mg tonight. Then follow up with your PCP for INR checks."
    },
    {
      "turn_number": 54,
      "time": "2159-09-17 07:13:00",
      "speaker": "Patient",
      "text": "Got it. Thank you again."
    },
    {
      "turn_number": 55,
      "time": "2159-09-17 07:14:00",
      "speaker": "Doctor",
      "text": "You’re doing great. Just keep up with your appointments and call if anything changes."
    },
    {
      "turn_number": 56,
      "time": "2159-09-17 07:15:00",
      "speaker": "Patient",
      "text": "I will. I’m feeling much better already."
    },
    {
      "turn_number": 57,
      "time": "2159-09-17 07:16:00",
      "speaker": "Doctor",
      "text": "That’s what we like to hear. We’ll see you in clinic soon."
    },
    {
      "turn_number": 58,
      "time": "2159-09-17 07:17:00",
      "speaker": "Patient",
      "text": "Looking forward to it. Thanks for explaining everything."
    },
    {
      "turn_number": 59,
      "time": "2159-09-17 07:18:00",
      "speaker": "Doctor",
      "text": "Of course. Take care, Ms. ___."
    },
    {
      "turn_number": 60,
      "time": "2159-09-17 07:19:00",
      "speaker": "Patient",
      "text": "You too."
    },
    {
      "turn_number": 61,
      "time": "2159-09-17 07:20:00",
      "speaker": "Doctor",
      "text": "Nurse will be in with your discharge meds and instructions."
    },
    {
      "turn_number": 62,
      "time": "2159-09-17 07:21:00",
      "speaker": "Patient",
      "text": "Okay, I’m ready."
    },
    {
      "turn_number": 63,
      "time": "2159-09-17 07:22:00",
      "speaker": "Doctor",
      "text": "Great. We’ll get you out of here soon."
    },
    {
      "turn_number": 64,
      "time": "2159-09-17 07:23:00",
      "speaker": "Patient",
      "text": "Appreciate it."
    },
    {
      "turn_number": 65,
      "time": "2159-09-17 07:24:00",
      "speaker": "Doctor",
      "text": "Take it easy at home and keep that foot elevated."
    },
    {
      "turn_number": 66,
      "time": "2159-09-17 07:25:00",
      "speaker": "Patient",
      "text": "I will. Thank you."
    },
    {
      "turn_number": 67,
      "time": "2159-09-17 07:26:00",
      "speaker": "Doctor",
      "text": "You’re welcome. Have a safe trip home."
    }
  ],
  "summary": {
    "admission_start": "2159-09-11 23:01:00",
    "admission_end": "2159-09-17 17:31:00",
    "summary_paragraph": "A woman with a history of mechanical aortic valve replacement, end-stage renal disease on dialysis, coronary artery disease, peripheral vascular disease, and prior right below-knee amputation was admitted for nausea, vomiting, and hypertensive urgency. She presented with uncontrolled hypertension, elevated troponin likely due to demand ischemia, and an anion gap metabolic acidosis attributed to sodium thiosulfate from dialysis. A CT head revealed a nonspecific medullary hyperdensity, but the patient declined recommended MRI follow-up. She was transferred to Vascular Surgery and underwent a left first and second toe amputation due to dry gangrene, with the procedure scaled down as the gangrene had improved. Her blood pressure was stabilized with a regimen of labetalol, amlodipine, and hydralazine, and anticoagulation was bridged with heparin before restarting warfarin. She recovered well postoperatively, with controlled symptoms and a clean wound, and was discharged home with visiting nurse services for wound care and follow-up appointments in vascular surgery and nephrology.",
    "problems": [
      "Hypertensive chronic kidney disease, unspecified, with chronic kidney disease stage V or end stage renal disease",
      "End stage renal disease",
      "Gangrene",
      "Acidosis",
      "Nausea with vomiting",
      "Peripheral vascular disease, unspecified",
      "Below knee amputation status",
      "Renal dialysis status",
      "Heart valve replaced by other means",
      "Long-term (current) use of anticoagulants",
      "Long-term (current) use of antiplatelet/antithrombotic"
    ]
  }
}
